struct Service { virtual Response call(const Request&) = 0; virtual ~Service() = default; };
class Gate : public Service {
  std::unique_ptr<Service> next_; Policy policy_;
 public:
  Gate(std::unique_ptr<Service> next, Policy p) : next_(std::move(next)), policy_(std::move(p)) {}
  Response call(const Request& r) override {
    auto id = verify(r);                 // this gate's own evidence
    if (!policy_.allows(id, r)) throw Denied{};    // fail closed
    return next_->call(r);               // delegate inward, not merge
  }
};
